// KlagonOrg payments relay — Moolre webhook receiver + donation charge endpoint.
//
// Secrets (wrangler secret put): SUPABASE_ANON_KEY, CALLBACK_KEY,
//   MOOLRE_USER, MOOLRE_PUBKEY, MOOLRE_WALLET, TURNSTILE_SECRET,
//   BREVO_API_KEY, CONFIRM_SECRET, FOLLOWUP_KEY, EMAIL_TEST_KEY.
//
// CONFIRM_SECRET is the shared secret that every confirm_*_by_ref RPC, plus
// create_course_order and create_sponsor_order, requires via the
// x-confirm-secret header. It is generated by
// supabase/migrations/20261003070000_course_payments.sql and must be copied out
// of public.app_secrets into this worker.

const MOOLRE_WALLET_CALLBACK_IP = "192.241.135.134";
const MOOLRE_API = "https://api.moolre.com/open/transact/payment";
const MOOLRE_STATUS_API = "https://api.moolre.com/open/transact/status";
const TURNSTILE_VERIFY = "https://challenges.cloudflare.com/turnstile/v0/siteverify";

const PAID_SIGNALS = new Set(["success", "successful", "completed", "paid", "1"]);
const FAILED_SIGNALS = new Set(["failed", "failure", "cancelled", "canceled", "rejected", "0"]);

// Browsers allowed to call the charge endpoint (the site + its previews).
function corsHeaders(origin) {
  const allowed =
    origin === "https://klagon.org" ||
    origin === "https://www.klagon.org" ||
    (typeof origin === "string" && origin.endsWith(".klagon-org.pages.dev"));
  return {
    "Content-Type": "application/json",
    ...(allowed ? { "Access-Control-Allow-Origin": origin } : {}),
    "Access-Control-Allow-Methods": "POST, GET, OPTIONS",
    "Access-Control-Allow-Headers": "Authorization, Content-Type",
  };
}

function json(obj, status = 200, origin = "") {
  return new Response(JSON.stringify(obj), { status, headers: corsHeaders(origin) });
}

const CHANNELS = { mtn: "13", telecel: "6", at: "7" };

function normalizeGhPhone(raw) {
  const digits = String(raw ?? "").replace(/[\s-]/g, "");
  if (/^0\d{9}$/.test(digits)) return digits;
  const m = digits.match(/^\+233(\d{9})$/);
  if (m) return `0${m[1]}`;
  return null;
}

function sbHeaders(env) {
  return {
    apikey: env.SUPABASE_ANON_KEY,
    Authorization: `Bearer ${env.SUPABASE_ANON_KEY}`,
    "Content-Type": "application/json",
  };
}

function sbRpc(env, fn, body) {
  return fetch(`${env.SUPABASE_URL}/rest/v1/rpc/${fn}`, {
    method: "POST",
    headers: sbHeaders(env),
    body: JSON.stringify(body),
  });
}

// Payment mutating RPCs require a worker-only shared secret; the guard lives in
// the database (confirm_secret_ok). Reads that grant nothing use sbRpc.
function sbRpcSigned(env, fn, body) {
  return fetch(`${env.SUPABASE_URL}/rest/v1/rpc/${fn}`, {
    method: "POST",
    headers: { ...sbHeaders(env), "x-confirm-secret": env.CONFIRM_SECRET ?? "" },
    body: JSON.stringify(body),
  });
}

// Resolve a signed-in member from the browser's Supabase access token. Used so
// a course purchase always attaches to a real auth.uid() the caller cannot
// spoof by naming someone else.
async function authUserId(env, request) {
  const auth = request.headers.get("Authorization") ?? "";
  const token = auth.startsWith("Bearer ") ? auth.slice(7).trim() : "";
  if (!token) return null;
  try {
    const res = await fetch(`${env.SUPABASE_URL}/auth/v1/user`, {
      headers: { apikey: env.SUPABASE_ANON_KEY, Authorization: `Bearer ${token}` },
    });
    if (!res.ok) return null;
    const user = await res.json();
    return typeof user?.id === "string" ? user.id : null;
  } catch {
    return null;
  }
}

// Ref prefixes route the single Moolre callback to the right order table.
// Donation refs are the bare KLG- prefix with no sub-prefix.
const KLG_REF_PREFIX = "KLG-";
const BOOST_REF_PREFIX = "KLG-B-";
const SPONSOR_REF_PREFIX = "KLG-S-";
const COURSE_REF_PREFIX = "KLG-C-";

// Self-serve sponsorship tiers. 'strategic' is bespoke (enquire off-platform).
const SELF_SERVE_SPONSOR_TIERS = new Set(["community", "growth", "talent", "digital"]);

const failRow = (env, ref) =>
  sbRpcSigned(env, "confirm_donation_by_ref", { p_ref: ref, p_status: "failed" }).catch(() => null);

const failBoostRow = (env, ref) =>
  sbRpcSigned(env, "confirm_boost_payment_by_ref", { p_ref: ref, p_status: "failed" }).catch(() => null);

const failSponsorRow = (env, ref) =>
  sbRpcSigned(env, "confirm_sponsor_payment_by_ref", { p_ref: ref, p_status: "failed" }).catch(() => null);

const failCourseRow = (env, ref) =>
  sbRpcSigned(env, "confirm_course_payment_by_ref", { p_ref: ref, p_status: "failed" }).catch(() => null);

const BREVO_API = "https://api.brevo.com/v3/smtp/email";
const BREVO_FROM = { name: "KlagonOrg Team", email: "hello@klagon.org" };

async function brevoSend(env, to, subject, html) {
  if (!env.BREVO_API_KEY || !to?.length) return null;
  const res = await fetch(BREVO_API, {
    method: "POST",
    headers: {
      "api-key": env.BREVO_API_KEY,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({ sender: BREVO_FROM, to, subject, htmlContent: html }),
  });
  return res.json();
}

async function sendDonationEmails(env, ref) {
  const res = await fetch(`${env.SUPABASE_URL}/rest/v1/rpc/get_donation_sendable`, {
    method: "POST",
    headers: {
      apikey: env.SUPABASE_ANON_KEY,
      Authorization: `Bearer ${env.SUPABASE_ANON_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ p_ref: ref }),
  });
  const row = res.ok ? (await res.json())[0] : null;
  if (!row) return;

  const amount = Number(row.amount_ghs ?? 0).toFixed(2);
  const rowName = String(row.full_name || "").trim();
  const name = rowName ? rowName.split(" ")[0] : "Friend";

  if (row.email) {
    await brevoSend(
      env,
      [{ email: String(row.email).trim(), name }],
      `Your KlagonOrg donation of GH₵${amount}`,
      `<p>Hi ${name},</p><p>Thank you for your donation of <strong>GH\u00a5${amount}</strong> to KlagonOrg (ref <code>${ref}</code>).</p><p>Your support helps advance our mission. Follow progress at <a href="https://klagon.org">klagon.org</a>.</p>`
    ).catch(() => null);
  }

  await brevoSend(
    env,
    [{ email: "klagonorg@gmail.com", name: "KlagonOrg Admin" }],
    `New donation received — GH₵${amount}`,
    `<p>Reference: <code>${ref}</code></p><p>Name: ${rowName || "Anonymous"}</p><p>Amount: GH\u00a5${amount}</p><p>Email: ${row.email || "—"}</p>`
  ).catch(() => null);
}

