function firstTokenName(name) {
  const n = String(name || "").trim().split(" ")[0];
  return n || "Friend";
}

async function handleAutoreply(request, env) {
  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "bad-json" }, 400);
  }
  if (!env.FOLLOWUP_KEY || request.headers.get("x-followup-key") !== env.FOLLOWUP_KEY) {
    return json({ error: "forbidden" }, 403);
  }
  const tpl = AUTOREPLY_TEMPLATES[body.kind];
  const to = String(body.to || "").trim();
  if (!tpl || !to) return json({ error: "unknown-kind" }, 400);
  const name = firstTokenName(body.name);
  const result = await brevoSend(
    env,
    [{ email: to, name }],
    tpl.subject(name),
    tpl.html(name, body.ref)
  ).catch(() => null);
  return json({ ok: true, result });
}

async function moolreCollect(env, { channel, payer, amount, ref, network, otp }) {
  const res = await fetch(MOOLRE_API, {
    method: "POST",
    headers: {
      "X-API-USER": env.MOOLRE_USER,
      "X-API-PUBKEY": env.MOOLRE_PUBKEY,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      type: 1,
      channel,
      currency: "GHS",
      payer,
      amount: String(amount),
      externalref: ref,
      ...(otp ? { otpcode: String(otp) } : {}),
      reference: `KlagonOrg ${orderKind(ref)} ${ref}`,
      accountnumber: env.MOOLRE_WALLET,
    }),
  });
  return res.json();
}

// Resolve a ref to its order kind. Throws on anything that is not a Klagon ref:
// every prefix we mint starts with KLG-, so a ref that matches none of them is a
// bug or a probe. This used to fall through to "donation", which meant a
// mistyped or future-provider prefix would settle against the donations table
// instead of erroring — silent, and it would have misrouted card payments as
// soon as a second provider landed.
function orderKind(ref) {
  if (ref.startsWith(BOOST_REF_PREFIX)) return "boost";
  if (ref.startsWith(SPONSOR_REF_PREFIX)) return "sponsor";
  if (ref.startsWith(COURSE_REF_PREFIX)) return "course";
  if (ref.startsWith(KLG_REF_PREFIX)) return "donation";
  throw new Error("unrecognised order reference");
}

function confirmFnFor(kind) {
  return kind === "boost"
    ? "confirm_boost_payment_by_ref"
    : kind === "sponsor"
    ? "confirm_sponsor_payment_by_ref"
    : kind === "course"
    ? "confirm_course_payment_by_ref"
    : "confirm_donation_by_ref";
}

// Ask Moolre for the final status of a reference. The callback is the primary
// settlement path, but webhooks get dropped; this is the reconciliation path so
// a missed callback can never strand an order as pending forever.
async function moolreStatus(env, ref) {
  const res = await fetch(MOOLRE_STATUS_API, {
    method: "POST",
    headers: {
      "X-API-USER": env.MOOLRE_USER,
      "X-API-PUBKEY": env.MOOLRE_PUBKEY,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ type: 1, idtype: 1, id: ref, accountnumber: env.MOOLRE_WALLET }),
  });
  return res.json();
}

function moolreOutcome(payload) {
  const code = String(payload?.code ?? "");
  const message = String(payload?.message ?? "");
  const tx = payload?.data?.txstatus;
  const txStr = String(tx ?? "").toLowerCase();
  if (code === "SS01" || tx === 1 || PAID_SIGNALS.has(txStr) || /success/i.test(message)) {
    return "paid";
  }
  if (FAILED_SIGNALS.has(txStr) || tx === -1 || /fail|cancel|reject|declin/i.test(message)) {
    return "failed";
  }
  return "pending";
}

// Returns the order kind and whether this call actually moved a pending row.
// The confirm RPCs answer that now; when they returned void the worker could not
// tell "just settled" from "already settled long ago", so it reported success
// and sent receipts for refs it had never seen.
async function settleOrder(env, ref, status) {
  const kind = orderKind(ref);
  const res = await sbRpcSigned(env, confirmFnFor(kind), { p_ref: ref, p_status: status });
  if (!res.ok) throw new Error((await res.text()).slice(0, 200));
  const moved = (await res.json()) === true;
  return { kind, moved };
}

async function handlePaymentStatus(request, env) {
  const origin = request.headers.get("Origin") ?? "";

  let ref = "";
  if (request.method === "GET") {
    ref = String(new URL(request.url).searchParams.get("ref") ?? "").trim();
  } else {
    let input;
    try {
      input = await request.json();
    } catch {
      return json({ error: "Send a ref." }, 400, origin);
    }
    ref = String(input?.ref ?? "").trim();
  }
  if (!ref) return json({ error: "Send a ref." }, 400, origin);

  // Resolve the order type before spending an upstream call. An unrecognised
  // ref is a client error, not something to settle.
  let kind;
  try {
    kind = orderKind(ref);
  } catch {
    return json({ error: "Unknown payment reference." }, 400, origin);
  }

  if (!env.MOOLRE_USER || !env.MOOLRE_PUBKEY || !env.MOOLRE_WALLET) {
    return json({ error: "Online payments are not switched on yet." }, 503, origin);
  }

  let payload;
  try {
    payload = await moolreStatus(env, ref);
  } catch {
    return json({ error: "Payment service unreachable." }, 502, origin);
  }

  const outcome = moolreOutcome(payload);
  let settled = false;
  if (outcome !== "pending") {
    try {
      const { moved } = await settleOrder(env, ref, outcome);
      settled = moved;
      if (moved && outcome === "paid") {
        if (kind === "boost") await sendBoostEmails(env, ref).catch(() => null);
        else if (kind === "sponsor") await sendSponsorEmails(env, ref).catch(() => null);
        else if (kind === "course") await sendCourseEmails(env, ref).catch(() => null);
        else await sendDonationEmails(env, ref).catch(() => null);
      }
    } catch {
      return json({ error: "supabase-update-failed", provider: outcome }, 502, origin);
    }
  }

  // The raw provider code and message are deliberately not echoed: this route is
  // unauthenticated, and they leak Moolre's internal vocabulary to anyone who
  // can reach the worker.
  return json({ ok: true, ref, kind, provider: outcome, settled }, 200, origin);
}

async function handleCharge(request, env) {
  const origin = request.headers.get("Origin") ?? "";

  let input;
  try {
    input = await request.json();
  } catch {
    return json({ error: "Send amount, phone and network." }, 400, origin);
  }

  const amount = Number(input?.amount_ghs);
  if (!Number.isFinite(amount) || amount <= 0) {
    return json({ error: "Enter a valid amount." }, 400, origin);
  }
  const channel = CHANNELS[String(input?.network ?? "").toLowerCase()];
  if (!channel) {
    return json({ error: "Choose MTN, Telecel or AT." }, 400, origin);
  }
  const payer = normalizeGhPhone(input?.phone);
  if (!payer) {
    return json({ error: "Enter a valid 10-digit Ghana phone number." }, 400, origin);
  }

  if (!env.MOOLRE_USER || !env.MOOLRE_PUBKEY || !env.MOOLRE_WALLET) {
    return json({ error: "Online payments are not switched on yet. Please try again later." }, 503, origin);
  }

  const ref = `KLG-${Date.now().toString(36)}-${crypto.randomUUID().slice(0, 8)}`.toUpperCase();

  // 1) Pending row first (anon insert allowed for status='pending' by RLS).
  try {
    const res = await fetch(`${env.SUPABASE_URL}/rest/v1/donations`, {
      method: "POST",
      headers: {
        apikey: env.SUPABASE_ANON_KEY,
        Authorization: `Bearer ${env.SUPABASE_ANON_KEY}`,
        "Content-Type": "application/json",
        Prefer: "return=minimal",
      },
      body: JSON.stringify({
        amount_ghs: amount,
        tier_id: input?.tier_id ?? null,
        full_name: input?.full_name || null,
        phone: payer,
        email: input?.email || null,
        status: "pending",
        provider: "moolre",
        provider_ref: ref,
        metadata: { network: String(input.network).toLowerCase() },
      }),
    });
    if (!res.ok) {
      return json({ error: "Could not start your donation. Please try again." }, 502, origin);
    }
  } catch {
    return json({ error: "Could not start your donation. Please try again." }, 502, origin);
  }

  // 2) Fire the payment request.
  let moolre;
  try {
    moolre = await moolreCollect(env, { channel, payer, amount, ref, network: input.network });
  } catch {
    await failRow(env, ref);
    return json({ error: "Payment service unreachable. Please try again." }, 502, origin);
  }

  const code = moolre?.code ? String(moolre.code) : "";
  if (moolre?.status == 1) {
    if (code === "TR099") {
      return json({ ok: true, ref, payer, message: "prompt-sent" }, 200, origin);
    }
    if (code === "TP14") {
      // OTP required: keep the row pending; the donor enters the SMS code next.
      return json({ ok: true, ref, payer, otp_required: true, message: "otp-required" }, 200, origin);
    }
    // Any other success-family code (e.g. TP17) = initiated; callback settles it.
    return json({ ok: true, ref, payer, message: "initiated" }, 200, origin);
  }

  await failRow(env, ref);
  return json(
    {
      error: moolre?.message ? String(moolre.message) : "Payment request failed. Please try again.",
      code,
    },
    502,
    origin
  );
}

async function handleConfirm(request, env) {
  const origin = request.headers.get("Origin") ?? "";

  let input;
  try {
    input = await request.json();
  } catch {
    return json({ error: "Send ref and otp." }, 400, origin);
  }

  const ref = String(input?.ref ?? "").trim();
  const otp = String(input?.otp ?? "").replace(/\s/g, "");
  if (!ref || otp.length < 4) {
    return json({ error: "Enter the full OTP from the SMS." }, 400, origin);
  }
  const amount = Number(input?.amount_ghs);
  const channel = CHANNELS[String(input?.network ?? "").toLowerCase()];
  const payer = normalizeGhPhone(input?.phone);

  let moolre;
  try {
    moolre = await moolreCollect(env, {
      channel: channel ?? "13",
      payer: payer ?? input?.phone,
      amount: Number.isFinite(amount) && amount > 0 ? amount : input?.amount_ghs,
      ref,
      network: input?.network,
      otp,
    });
  } catch {
    return json({ error: "Payment service unreachable. Please try again." }, 502, origin);
  }

  const code = moolre?.code ? String(moolre.code) : "";
  if (moolre?.status == 1) {
    return json({ ok: true, ref, message: code === "TR099" ? "prompt-sent" : "initiated" }, 200, origin);
  }

  return json(
    {
      error: moolre?.message ? String(moolre.message) : "Verification failed. Check the code and try again.",
      code,
    },
    400,
    origin
  );
}

// ---------- paid boosts ----------
// Boosts charge a server-derived fee (boost_quote), never a client amount.
// Orders live in boost_payments; confirm_boost_payment_by_ref flips them and
// applies the placement, so the browser never touches boost_until.
async function handleBoostCharge(request, env) {
  const origin = request.headers.get("Origin") ?? "";

  let input;
  try {
    input = await request.json();
  } catch {
    return json({ error: "Send a listing, phone and network." }, 400, origin);
  }

  const postId = String(input?.post_id ?? "").trim();
  if (!/^[0-9a-f-]{36}$/i.test(postId)) {
    return json({ error: "Pick a listing to feature." }, 400, origin);
  }
  const channel = CHANNELS[String(input?.network ?? "").toLowerCase()];
  if (!channel) {
    return json({ error: "Choose MTN, Telecel or AT." }, 400, origin);
  }
  const payer = normalizeGhPhone(input?.phone);
  if (!payer) {
    return json({ error: "Enter a valid 10-digit Ghana phone number." }, 400, origin);
  }

  if (!env.MOOLRE_USER || !env.MOOLRE_PUBKEY || !env.MOOLRE_WALLET) {
    return json({ error: "Online payments are not switched on yet. Please try again later." }, 503, origin);
  }

  // The price is whatever the database says; an ineligible listing returns none.
  let quote = null;
  try {
    const res = await sbRpc(env, "boost_quote", { p_post_id: postId });
    if (res.ok) {
      const rows = await res.json();
      quote = Array.isArray(rows) ? rows[0] : null;
    }
  } catch {
    quote = null;
  }
  if (!quote) {
    return json({ error: "This listing can’t be featured right now." }, 409, origin);
  }

  const amount = Number(quote.fee_ghs);
  const days = Number(quote.days);
  const tier = String(quote.tier);

  const ref = `${BOOST_REF_PREFIX}${Date.now().toString(36)}-${crypto.randomUUID().slice(0, 8)}`.toUpperCase();

  // 1) Pending order first (anon insert allowed for status='pending' by RLS).
  try {
    const res = await fetch(`${env.SUPABASE_URL}/rest/v1/boost_payments`, {
      method: "POST",
      headers: { ...sbHeaders(env), Prefer: "return=minimal" },
      body: JSON.stringify({
        post_id: postId,
        tier,
        amount_ghs: amount,
        days,
        status: "pending",
        provider: "moolre",
        provider_ref: ref,
        payer_phone: payer,
        network: String(input.network).toLowerCase(),
      }),
    });
    if (!res.ok) {
      return json({ error: "Could not start your boost. Please try again." }, 502, origin);
    }
  } catch {
    return json({ error: "Could not start your boost. Please try again." }, 502, origin);
  }

  // 2) Fire the payment request.
  let moolre;
  try {
    moolre = await moolreCollect(env, { channel, payer, amount, ref, network: input.network });
  } catch {
    await failBoostRow(env, ref);
    return json({ error: "Payment service unreachable. Please try again." }, 502, origin);
  }

  const code = moolre?.code ? String(moolre.code) : "";
  if (moolre?.status == 1) {
    if (code === "TP14") {
      return json({ ok: true, ref, payer, otp_required: true, amount_ghs: amount, days, tier, message: "otp-required" }, 200, origin);
    }
    return json(
      { ok: true, ref, payer, amount_ghs: amount, days, tier, message: code === "TR099" ? "prompt-sent" : "initiated" },
      200,
      origin
    );
  }

  await failBoostRow(env, ref);
  return json(
    {
      error: moolre?.message ? String(moolre.message) : "Payment request failed. Please try again.",
      code,
    },
    502,
    origin
  );
}

