// ---------- paid courses (one-time, lifetime access) ----------
// Buying a course requires a signed-in member: the browser's Supabase access
// token is verified here and the resulting uid is what the order is attached
// to, so entitlements can never be attached to someone else's account.
async function handleCourseCharge(request, env) {
  const origin = request.headers.get("Origin") ?? "";

  let input;
  try {
    input = await request.json();
  } catch {
    return json({ error: "Send a course, phone and network." }, 400, origin);
  }

  const courseId = String(input?.course_id ?? "").trim();
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(courseId)) {
    return json({ error: "Pick a course." }, 400, origin);
  }
  const channel = CHANNELS[String(input?.network ?? "").toLowerCase()];
  if (!channel) {
    return json({ error: "Choose MTN, Telecel or AT." }, 400, origin);
  }
  const payer = normalizeGhPhone(input?.phone);
  if (!payer) {
    return json({ error: "Enter a valid 10-digit Ghana phone number." }, 400, origin);
  }

  if (!env.MOOLRE_USER || !env.MOOLRE_PUBKEY || !env.MOOLRE_WALLET) {
    return json({ error: "Online payments are not switched on yet. Please try again later." }, 503, origin);
  }
  if (!env.CONFIRM_SECRET) {
    return json({ error: "Online payments are not switched on yet. Please try again later." }, 503, origin);
  }

  const memberId = await authUserId(env, request);
  if (!memberId) {
    return json({ error: "Please sign in to buy this course.", code: "auth-required" }, 401, origin);
  }

  const ref = `${COURSE_REF_PREFIX}${Date.now().toString(36)}-${crypto.randomUUID().slice(0, 8)}`.toUpperCase();

  // The RPC re-derives the price from courses.price_ghs; the browser never
  // names its own fee.
  let order = null;
  try {
    const res = await sbRpcSigned(env, "create_course_order", {
      p_course_id: courseId,
      p_member_id: memberId,
      p_phone: payer,
      p_network: String(input.network).toLowerCase(),
      p_provider_ref: ref,
    });
    if (res.ok) {
      const rows = await res.json();
      order = Array.isArray(rows) ? rows[0] : null;
    }
  } catch {
    order = null;
  }
  if (!order) {
    return json({ error: "This course can't be purchased right now." }, 409, origin);
  }

  const amount = Number(order.amount_ghs);

  let moolre;
  try {
    moolre = await moolreCollect(env, { channel, payer, amount, ref, network: input.network });
  } catch {
    await failCourseRow(env, ref);
    return json({ error: "Payment service unreachable. Please try again." }, 502, origin);
  }

  const code = moolre?.code ? String(moolre.code) : "";
  if (moolre?.status == 1) {
    if (code === "TP14") {
      return json({ ok: true, ref, payer, otp_required: true, amount_ghs: amount, course_id: courseId, message: "otp-required" }, 200, origin);
    }
    return json(
      { ok: true, ref, payer, amount_ghs: amount, course_id: courseId, message: code === "TR099" ? "prompt-sent" : "initiated" },
      200,
      origin
    );
  }

  await failCourseRow(env, ref);
  return json(
    {
      error: moolre?.message ? String(moolre.message) : "Payment request failed. Please try again.",
      code,
    },
    502,
    origin
  );
}

